#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 3);
bool automaticMode = true;
int lastRawButton = HIGH;
int stableButton = HIGH;
unsigned long rawChangedAt = 0;
unsigned long lastUpdate = 0;
bool firstUpdate = true;

void updateOutputs() {
  int temperatureRaw = analogRead(A1);
  int potentiometer = analogRead(A0);
  float temperatureC = temperatureRaw * (500.0f / 1023.0f);
  int pwm;
  int shown;
  if (automaticMode) {
    float requested = temperatureC * 255.0f / 100.0f;
    if (requested < 0.0f) requested = 0.0f;
    if (requested > 255.0f) requested = 255.0f;
    pwm = (int)(requested + 0.5f);
    shown = (int)(temperatureC + 0.5f);
  } else {
    pwm = (int)((potentiometer * 255L + 511L) / 1023L);
    shown = (int)((potentiometer * 10L + 511L) / 1023L);
  }
  analogWrite(5, pwm);
  display.showNumberDec(shown, false);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(5, OUTPUT);
  display.setBrightness(7);
  updateOutputs();
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRawButton) {
    lastRawButton = raw;
    rawChangedAt = now;
  }
  if (raw != stableButton && now - rawChangedAt >= 40UL) {
    stableButton = raw;
    if (stableButton == LOW) {
      automaticMode = !automaticMode;
      updateOutputs();
    }
  }
  if (firstUpdate || now - lastUpdate >= 100UL) {
    firstUpdate = false;
    lastUpdate = now;
    updateOutputs();
  }
}
